queries.sql:
select * from tbl_tarif_spp a
        left join setup_periode b on a.periode = b.id_periode
        where b.status_aktif = &#039;yes&#039;

select * from VSISWAKELAS a left join setup_kelas b on a.id_kelas= b.id_kelas
        <strong>LEFT</strong> join tbl_peserta_loundry c on a.id_siswa = c.id_siswa
        left join tbl_spp d on a.id_siswa = d.nis where c.peserta = &#039;yes&#039; and a.id_siswa = &#039;400&#039;

